<?php require_once 'includes/config.php';require_admin();
$msg = null;
$error = null;$id=(int)($_GET['id']??$_POST['id']??0);$q=$dbh->prepare('SELECT * FROM teachers WHERE id=:id');$q->execute([':id'=>$id]);$t=$q->fetch();if(!$t)exit('Teacher not found.');$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['full_name']??'');$e=trim($_POST['email']??'');$g=trim($_POST['gender']??'');if(!$n)$error='Full name is required.';elseif($e&&!filter_var($e,FILTER_VALIDATE_EMAIL))$error='Invalid email.';else{try{$u=$dbh->prepare('UPDATE teachers SET full_name=:n,email=:e,gender=:g,status=:s,updated_at=NOW() WHERE id=:id');$u->execute([':n'=>$n,':e'=>$e?:null,':g'=>$g?:null,':s'=>(int)($_POST['status']??1),':id'=>$id]);audit_log($dbh,'TEACHER_UPDATE','Updated teacher '.$id);$msg='Teacher updated.';$q->execute([':id'=>$id]);$t=$q->fetch();}catch(PDOException $x){$error='Email may already be in use.';}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Teacher | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container srms-page"><a href="manage-teachers.php" class="btn btn-default">← Teachers</a><div class="panel m-t-20"><div class="panel-heading"><h3>Edit Teacher</h3></div><div class="panel-body"><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?><form method="post"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo $id;?>"><div class="form-group"><label>Username</label><input class="form-control" value="<?php echo e($t['username']);?>" readonly></div><div class="form-group"><label>Full Name</label><input class="form-control" name="full_name" value="<?php echo e($t['full_name']);?>" required></div><div class="form-group"><label>Email</label><input class="form-control" type="email" name="email" value="<?php echo e($t['email']);?>"></div><div class="form-group"><label>Gender</label><select class="form-control" name="gender"><option value="">Select gender</option><option value="Male" <?php echo $t['gender']==='Male'?'selected':'';?>>Male</option><option value="Female" <?php echo $t['gender']==='Female'?'selected':'';?>>Female</option><option value="Other" <?php echo $t['gender']==='Other'?'selected':'';?>>Other</option></select></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="1" <?php echo $t['status']?'selected':'';?>>Active</option><option value="0" <?php echo !$t['status']?'selected':'';?>>Inactive</option></select></div><button class="btn btn-primary">Update Teacher</button></form></div></div></div></main></div></div></div></div></body></html>
